// Convert polygon coordinates to 3D points projected onto the plane
std::vector<Kernel::Point_3> projected_points;
for (const auto& coord : polygon_coords) {
    Kernel::Point_3 p(coord[0], coord[1], 0.0);
    projected_points.push_back(plane.to_3d(p));
}

// Insert vertices into the triangulation
std::vector<Triangulation::Vertex_handle> vertices;
for (const auto& point : projected_points) {
    vertices.push_back(triangulation.insert(point, walk_start));
}

// Insert polygon constraints
for (std::size_t i = 0; i < vertices.size(); ++i) {
    std::size_t j = (i + 1) % vertices.size();
    triangulation.odd_even_insert_constraint(vertices[i], vertices[j]);
}

// Ensure the polygon is closed by adding the last constraint
if (!vertices.empty()) {
    triangulation.odd_even_insert_constraint(vertices.back(), vertices.front());
}

